    convo = "\n\n".join(f"[{m.get('role', '?')}] {_msg_text(m)}" for m in middle)
    try:
        a = provider.chat([{"role": "system", "content": _SUMMARY_PROMPT},
                           {"role": "user", "content": convo[:60_000]}],
                          tools=None, on_text=None, cancel=cancel)
