def _heuristic_scores(text: str) -> dict[TaskType, int]:
    low = (text or "").lower()
    scores: dict[TaskType, int] = {tt: 0 for tt in TaskType}
    for tt, entries in _COMPILED.items():
        for raw, pat in entries:
            if pat is not None:
                if pat.search(low):
                    scores[tt] += 1
            elif raw in low:
                scores[tt] += 1
    return scores

