def _cost_term(metadata: ModelMetadata) -> float:
    """Normalized cost term ``1/(1+cost)`` in ``(0, 1]`` — higher is cheaper."""
    cost = metadata.avg_cost_per_1k
    if cost is None:
        cost = _UNKNOWN_COST_PER_1K
    cost = max(0.0, float(cost))
    return 1.0 / (1.0 + cost)

