def _latency_term(probe: ProbeResult) -> float:
    """Normalized latency term ``1/(1+latency_s)`` in ``(0, 1]`` — higher is faster."""
    latency_s = max(0.0, float(probe.latency_ms)) / 1000.0
    return 1.0 / (1.0 + latency_s)

