        try:
            out[key] = ModelAssessment.model_validate(payload)
        except Exception:  # noqa: BLE001 — skip a single corrupt entry
            continue
    return out

def history_files(self) -> list[Path]:
    """All history snapshots, oldest first (for degrade detection / UI)."""
