def stop(self) -> None:
    if not self._active:
        return
    for w in list(self._active):
        if w.isRunning():
            w.request_stop()
    self.composer.clear_queue()   # don't start anything still waiting
    self.status_message.emit(tr("chatpanel.stopping", name=tr(f"app.tab.{self.kind}")))

