def _towards(a: QPointF, b: QPointF, d: float) -> QPointF:
    dist = _dist(a, b)
    if dist < 1e-6:
        return QPointF(a)
    t = d / dist
    return QPointF(a.x() + (b.x() - a.x()) * t, a.y() + (b.y() - a.y()) * t)

