def _downstream(self, node_id: str) -> set:
    adj: Dict[str, List[str]] = {}
    for e in self.canvas.edges():
        adj.setdefault(e.source, []).append(e.target)
    seen, stack = set(), [node_id]
    while stack:
        cur = stack.pop()
        if cur in seen:
            continue
        seen.add(cur)
        stack.extend(adj.get(cur, []))
    return seen

