def _paths_from_mime(md) -> List[str]:
    paths: List[str] = []
    if md.hasUrls():
        for u in md.urls():
            if u.isLocalFile():
                paths.append(u.toLocalFile())
    if not paths and md.hasImage():
        p = _save_pasted_image(md.imageData())
        if p:
            paths.append(p)
    return paths

